// QA joint same-collection-two-viewers acceptance (l6-accounts 10.2, Tier 1):
// the per-viewer chain-mute contract over the FULL production path — a REAL
// cmd/mellifera server subprocess (the qaSerialStartServer harness, whose
// main.go wiring carries the production ModulePresentation closure reading
// the request Viewer via access.FromContext, the real enrich queue, the real
// art service + janitor settle, and Deps.Identity wired) running the REAL
// serial-scanner/serial-parser/frame-grabber/shikimori plugin subprocesses
// over a REAL fixture library, with the mute arriving through the REAL
// identity chain: admin-surface users + groups + the mute document
// (PUT /admin/groups/{id}/doc) + member-collection grants, REAL logins
// (POST /auth/login), viewerFor's per-request identity.ResolveViewer, and the
// three served legs (display walk, artwork walk, source_chain) reading the
// SAME stored rows for both viewers:
//
//   - enriched_baseline (setup, fatal not subtest): the fixture's series row
//     enriches through serial-parser → shikimori (search leg over the stub
//     upstream), landing both namespaces with the shikimori title AND poster
//     — the shared substrate every later differential stands on,
//   - muted_serve_floors: the muted viewer's served series/episode display
//     names floor to the parser title (never the RU pick), its composed
//     artwork omits the muted source (absent — the omitempty omitting), and
//     its library's source_chain carries shikimori with enabled=false,
//   - clean_serve_composes: the clean viewer (same stored rows, no mute doc)
//     composes the RU pick, the staged poster token, and enabled=true —
//   - chain_diff_is_enabled_only: a structural diff of the two serves'
//     source_chain EXCLUDING the enabled flag is byte-EMPTY — same plugin
//     ids, same order, same shape,
//   - stored_namespaces_byte_identical: the stored rows (the series and
//     episode documents carried verbatim by the wire, the title overrides,
//     the poster-override selections) read back byte-identical against the
//     PRE-SERVE admin baseline after BOTH viewers' serves and after every
//     group mutation — the floors are per-response and never persist,
//   - group_edits_wake_nothing: adding the muted user to a second group and
//     rewriting the mute document add ZERO upstream derive calls and zero
//     stored bytes — derivation is group-blind — while a FRESH serve after
//     the mute removal composes the restored source (the floors are live,
//     resolved per request, never frozen).
//
// HERMETIC: the library root anchors under t.TempDir() and the shikimori
// upstream is pinned to the local stub (qaSerialStartServer's
// MELLIFERA_SHIKIMORI_UPSTREAM env; the stub also serves the poster bytes so
// the art service's background acquisition can materialize the blob — its
// content address is precomputed from the served bytes, making the staged
// token deterministic, the 10.3 unit test's unstaged-expectation lesson).
// Fixture identity constants are independent of every other qa fixture
// (no-coincidence discipline). Every helper is qaTwoView-prefixed to stay
// collision-free in package itest.
package itest

import (
	"bytes"
	"encoding/json"
	"image"
	"image/color"
	"image/jpeg"
	"net/http"
	"net/http/httptest"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"
)

// Fixture identity constants. The trailing S01 marker is the season the
// shared grammar cuts from the clean title (the parser stamps it on the row
// and the shikimori Match derives the same search key); the anime id sits far
// from every other fixture's assignment; the account constants are
// lowercase-normalized usernames and display-name group names.
const (
	qaTwoViewDir       = "QA Two View Vault S01"
	qaTwoViewEp1Rel    = qaTwoViewDir + "/QA Two View Vault S01E01.mkv"
	qaTwoViewEp2Rel    = qaTwoViewDir + "/QA Two View Vault S01E02.mkv"
	qaTwoViewTitle     = "QA Two View Vault"       // the season cut — parser title AND search key
	qaTwoViewRussian   = "В Полёне Двойня"         // the walk's RU pick — the clean viewer's display
	qaTwoViewID        = 4771                      // the anime (search-selected)
	qaTwoViewPlugin    = "shikimori"               // the muted source id
	qaTwoViewPosterRel = "/images/animes/4771.jpg" // the stub-side poster path the payload carries

	qaTwoViewMutedUsername = "qa-two-view-muted"
	qaTwoViewCleanUsername = "qa-two-view-clean"
	qaTwoViewPassword      = "qa-two-view-passphrase-1"
	qaTwoViewMutedGroup    = "QA Two View Muted"
	qaTwoViewCleanGroup    = "QA Two View Clean"
)

// qaTwoViewJPEG encodes a small real JPEG whose pixels carry seed — the
// content address of the served bytes is what the staged artwork token names,
// so the clean viewer's composition is deterministic. Encode failure is
// impossible for this fixed image; a panic beats a silent zero-byte blob.
func qaTwoViewJPEG(seed byte) []byte {
	img := image.NewRGBA(image.Rect(0, 0, 30, 45)) // 2:3 portrait, poster-shaped
	for y := 0; y < 45; y++ {
		for x := 0; x < 30; x++ {
			img.Set(x, y, color.RGBA{R: seed, G: uint8(int(seed) + x), B: uint8(int(seed) + y), A: 255})
		}
	}
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, img, nil); err != nil {
		panic(err)
	}
	return buf.Bytes()
}

// qaTwoViewPoster is the poster blob the stub serves: real JPEG bytes whose
// content address the test precomputes, so the materialized token the clean
// viewer's artwork composes is deterministic.
var qaTwoViewPoster = qaTwoViewJPEG(0xB7)

// qaTwoViewInterval is the MELLIFERA_ART_INTERVAL knob value: the janitor's
// art task (settle) ticks this fast inside the REAL server, so the poster
// blob materializes in seconds without any test-side side-channel.
const qaTwoViewInterval = 250 * time.Millisecond

// qaTwoViewSettleTimeout bounds the wait for the art acquisition.
const qaTwoViewSettleTimeout = 30 * time.Second

// qaTwoViewTokenSHA is the content address of qaTwoViewPoster (the art token
// payload); qaTwoViewArtwork is the composed artwork URL once the blob is
// staged — the exact string the clean viewer's serves must carry.
var (
	qaTwoViewToken   = "art_" + qaArtSHA(qaTwoViewPoster)
	qaTwoViewArtwork = qaArtObjectPath + qaTwoViewToken
)

// qaTwoViewAnime builds one upstream anime payload whose name EQUALS the
// derived search title (single candidate, selection deterministic by
// construction) and whose image is the stub-served poster path (the plugin
// projects it absolute against the stub origin — the stored poster URL).
func qaTwoViewAnime() map[string]any {
	return map[string]any{
		"id": qaTwoViewID, "name": qaTwoViewTitle, "russian": qaTwoViewRussian,
		"kind": "tv", "status": "released", "score": "7.9", "episodes": 12,
		"aired_on": "2016-04-01", "description": "qa two-view stub",
		"url":   "/animes/" + strconv.Itoa(qaTwoViewID) + "-qa",
		"image": map[string]any{"original": qaTwoViewPosterRel},
		"genre": []any{map[string]any{"name": "Action", "russian": "Экшен"}},
	}
}

// qaTwoViewUpstream is the per-test fake shikimori origin: it records every
// request and serves THIS fixture's search list, by-id payload, and poster
// bytes (the API legs are the derive surface the wake-proof counts; the
// poster leg is the art service's materialization fetch — never a derive).
type qaTwoViewUpstream struct {
	baseURL string
	mu      sync.Mutex
	seen    []string // recorded "METHOD path" lines
}

func qaTwoViewStartUpstream(t *testing.T) *qaTwoViewUpstream {
	t.Helper()
	s := &qaTwoViewUpstream{}
	anime := qaTwoViewAnime()
	mux := http.NewServeMux()
	mux.HandleFunc(qaSerialUpstreamSearch, func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		if r.URL.Query().Get("search") != qaTwoViewTitle {
			http.NotFound(w, r)
			return
		}
		qaSerialWriteJSON(t, w, []map[string]any{anime})
	})
	mux.HandleFunc(qaSerialUpstreamSearch+"/", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		if strings.TrimPrefix(r.URL.Path, qaSerialUpstreamSearch+"/") != strconv.Itoa(qaTwoViewID) {
			http.NotFound(w, r)
			return
		}
		qaSerialWriteJSON(t, w, anime)
	})
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != qaTwoViewPosterRel {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "image/jpeg")
		_, _ = w.Write(qaTwoViewPoster)
	})
	hs := httptest.NewServer(mux)
	t.Cleanup(hs.Close)
	s.baseURL = hs.URL
	return s
}

func (s *qaTwoViewUpstream) record(r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.seen = append(s.seen, r.Method+" "+r.URL.Path)
}

// deriveCalls counts the recorded API derive legs (the search/by-id paths) —
// the wake-proof counter. Poster materialization fetches never land here.
func (s *qaTwoViewUpstream) deriveCalls() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for _, l := range s.seen {
		if strings.HasPrefix(l, "POST "+qaSerialUpstreamSearch) || strings.HasPrefix(l, "GET "+qaSerialUpstreamSearch) {
			n++
		}
	}
	return n
}

// snapshot copies the recorded request lines (the failure-dump surface —
// mutex-guarded, unlike a raw seen read).
func (s *qaTwoViewUpstream) snapshot() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]string(nil), s.seen...)
}

// qaTwoViewJoint is one composed two-viewer joint: the real server
// subprocess + the stub upstream + the serial library + the two viewers'
// session tokens.
type qaTwoViewJoint struct {
	srv    qaSerialServer
	client *http.Client
	admin  string // the env-admin token (operator surfaces + baseline serves)
	muted  string // the muted user's login session token
	clean  string // the clean user's login session token
	up     *qaTwoViewUpstream
	lib    int64
}

// qaTwoViewStartJoint boots the joint: the seven server-side binaries + the
// shikimori plugin, the REAL cmd/mellifera subprocess (production
// ModulePresentation closure, Deps.Identity wiring, art service + janitor),
// and the serial library over root. The scan stays with the caller.
func qaTwoViewStartJoint(t *testing.T, up *qaTwoViewUpstream, root string) *qaTwoViewJoint {
	t.Helper()
	// The janitor's art-task cadence, inherited by the subprocess at boot
	// (t.Setenv restores it; no test in this package runs parallel).
	t.Setenv("MELLIFERA_ART_INTERVAL", qaTwoViewInterval.String())
	tmp := t.TempDir()
	srv := qaSerialStartServer(t, qaSerialServerBins{
		server:        buildBinary(t, tmp, "qa-two-view-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "qa-two-view-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "qa-two-view-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "qa-two-view-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "qa-two-view-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "qa-two-view-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "qa-two-view-grabber", "./plugins/frame-grabber"),
	}, up.baseURL, tmp, "qa-two-view-admin-token")
	j := &qaTwoViewJoint{
		srv:    srv,
		client: &http.Client{Timeout: httpTimeout},
		admin:  "qa-two-view-admin-token",
		up:     up,
	}
	j.lib = qaSerialCreateLibrary(t, j.client, j.srv.baseURL, j.admin, root, "QA Two Viewers")
	return j
}

