// qaTwoViewCreateUser POSTs /admin/users and returns the created id.
func qaTwoViewCreateUser(t *testing.T, j *qaTwoViewJoint, username string) int64 {
	t.Helper()
	var resp struct {
		ID int64 `json:"id"`
	}
	status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/admin/users", j.admin,
		map[string]string{"username": username, "password": qaTwoViewPassword}, &resp)
	if status != http.StatusCreated {
		t.Fatalf("create user %s: HTTP %d, want 201", username, status)
	}
	if resp.ID == 0 {
		t.Fatalf("create user %s: zero id served", username)
	}
	return resp.ID
}

