func qaTwoViewSeriesRow(t *testing.T, rows []qaTwoViewSeries) qaTwoViewSeries {
	t.Helper()
	if len(rows) != 1 {
		t.Fatalf("series rows: %d served, want exactly 1: %+v", len(rows), rows)
	}
	return rows[0]
}

// qaTwoViewItemRow returns one item row by relative path (fatal when
// missing).
func qaTwoViewItemRow(t *testing.T, rows []qaTwoViewItem, rel string) qaTwoViewItem {
	t.Helper()
	for _, it := range rows {
		if it.RelativePath == rel {
			return it
		}
	}
	t.Fatalf("item %q missing from %d rows", rel, len(rows))
	return qaTwoViewItem{}
}

