// qaTwoViewSnapshot is the stored-namespace baseline: the series and episode
// documents (the wire carries the stored bytes verbatim, INV3), the title
// overrides (the pin rows), and the poster-override selections (the artwork
// override rows) — every stored namespace a serve could conceivably write.
type qaTwoViewSnapshot struct {
	SeriesDoc       []byte
	SeriesOverride  string
	SeriesSelection string
	Ep1Doc          []byte
	Ep1Override     string
	Ep1Selection    string
	Ep2Doc          []byte
	Ep2Override     string
	Ep2Selection    string
}

// qaTwoViewCapture takes one stored-namespace baseline as the env-admin (the
// operator serve — reads only, mute-blind by construction).
func qaTwoViewCapture(t *testing.T, j *qaTwoViewJoint, sr qaTwoViewSeries, ep1, ep2 qaTwoViewItem) qaTwoViewSnapshot {
	t.Helper()
	return qaTwoViewSnapshot{
		SeriesDoc:       append([]byte(nil), sr.Document...),
		SeriesOverride:  sr.TitleOverride,
		SeriesSelection: qaTwoViewPostersOf(t, j, "series", sr.ID).Current,
		Ep1Doc:          append([]byte(nil), ep1.Document...),
		Ep1Override:     ep1.TitleOverride,
		Ep1Selection:    qaTwoViewPostersOf(t, j, "items", ep1.ID).Current,
		Ep2Doc:          append([]byte(nil), ep2.Document...),
		Ep2Override:     ep2.TitleOverride,
		Ep2Selection:    qaTwoViewPostersOf(t, j, "items", ep2.ID).Current,
	}
}

// qaTwoViewRequireIdentical fails with a byte dump when a later capture
// drifted from the baseline.
func qaTwoViewRequireIdentical(t *testing.T, step string, baseline, now qaTwoViewSnapshot) {
	t.Helper()
	if !bytes.Equal(baseline.SeriesDoc, now.SeriesDoc) {
		t.Fatalf("%s: series document drifted:\nbefore: %s\nafter:  %s", step, baseline.SeriesDoc, now.SeriesDoc)
	}
	if !bytes.Equal(baseline.Ep1Doc, now.Ep1Doc) {
		t.Fatalf("%s: episode-1 document drifted:\nbefore: %s\nafter:  %s", step, baseline.Ep1Doc, now.Ep1Doc)
	}
	if !bytes.Equal(baseline.Ep2Doc, now.Ep2Doc) {
		t.Fatalf("%s: episode-2 document drifted:\nbefore: %s\nafter:  %s", step, baseline.Ep2Doc, now.Ep2Doc)
	}
	type pin struct {
		name, before, after string
	}
	for _, p := range []pin{
		{"series title override", baseline.SeriesOverride, now.SeriesOverride},
		{"series poster selection", baseline.SeriesSelection, now.SeriesSelection},
		{"episode-1 title override", baseline.Ep1Override, now.Ep1Override},
		{"episode-1 poster selection", baseline.Ep1Selection, now.Ep1Selection},
		{"episode-2 title override", baseline.Ep2Override, now.Ep2Override},
		{"episode-2 poster selection", baseline.Ep2Selection, now.Ep2Selection},
	} {
		if p.before != p.after {
			t.Fatalf("%s: %s drifted: %q → %q", step, p.name, p.before, p.after)
		}
	}
}

// qaTwoViewChainSansEnabled renders a source_chain with the enabled flags
// stripped — the structural diff input (marshaling the stripped entries
// keeps the comparison byte-exact over the whole shape).
func qaTwoViewChainSansEnabled(t *testing.T, chain []qaTwoViewBinding) []byte {
	t.Helper()
	type stripped struct {
		ID string `json:"id"`
	}
	out := make([]stripped, len(chain))
	for i, b := range chain {
		out[i] = stripped{ID: b.ID}
	}
	raw, err := json.Marshal(out)
	if err != nil {
		t.Fatalf("marshal stripped chain: %v", err)
	}
	return raw
}

// qaTwoViewAwaitArtwork polls the series grid as token until the row's
// artwork composes the STAGED token URL (the acquisition is a background
// handoff — the first serve carries the raw remote URL; staging is settled
// only when the content-addressed proxy URL appears), returning the row.
func qaTwoViewAwaitArtwork(t *testing.T, j *qaTwoViewJoint, token, want string) qaTwoViewSeries {
	t.Helper()
	deadline := time.Now().Add(qaTwoViewSettleTimeout)
	for time.Now().Before(deadline) {
		for _, sr := range qaTwoViewSeriesRows(t, j, token) {
			if sr.Artwork != nil && *sr.Artwork == want {
				return sr
			}
		}
		time.Sleep(probeInterval)
	}
	rows := qaTwoViewSeriesRows(t, j, token)
	t.Fatalf("artwork %q never staged within %s (last serve: %+v)", want, qaTwoViewSettleTimeout, rows)
	return qaTwoViewSeries{}
}

// qaTwoViewWriteFixtures writes the single-series fixture library root.
func qaTwoViewWriteFixtures(t *testing.T, root string) {
	t.Helper()
	qaSerialMedia(t, filepath.Join(root, qaTwoViewEp1Rel))
	qaSerialMedia(t, filepath.Join(root, qaTwoViewEp2Rel))
}

// qaTwoViewRequireFloored pins the MUTED serve's posture: every series and
// episode display composes the parser title (never the muted source's RU
// pick) and no artwork composes (the muted source owns the only poster).
func qaTwoViewRequireFloored(t *testing.T, j *qaTwoViewJoint, token string) {
	t.Helper()
	sr := qaTwoViewSeriesRow(t, qaTwoViewSeriesRows(t, j, token))
	if sr.Display != qaTwoViewTitle {
		t.Errorf("muted series display = %q, want the parser title %q (never the muted RU %q)", sr.Display, qaTwoViewTitle, qaTwoViewRussian)
	}
	if sr.Artwork != nil {
		t.Errorf("muted series artwork = %q, want absent (the muted source owns the only poster)", *sr.Artwork)
	}
	want := map[string]string{
		qaTwoViewEp1Rel: qaTwoViewTitle + " · S01E01",
		qaTwoViewEp2Rel: qaTwoViewTitle + " · S01E02",
	}
	for _, it := range qaTwoViewItemRows(t, j, token) {
		if it.Display != want[it.RelativePath] {
			t.Errorf("muted item %q display = %q, want the floored %q", it.RelativePath, it.Display, want[it.RelativePath])
		}
		if it.Artwork != nil {
			t.Errorf("muted item %q artwork = %q, want absent (the series fallback floors past the muted source too)", it.RelativePath, *it.Artwork)
		}
	}
}

// TestSameCollectionTwoViewers is the l6-accounts 10.2 joint acceptance
// floor (spec scenario "Two viewers observe different chains for the same
// collection" + "Group-blind derivation"): one collection, two REAL viewers —
// the muted one floors, the clean one composes, the chains differ only in
// the enabled flag, the stored namespaces never move, and group edits wake
// nothing while the floors stay live.
func TestSameCollectionTwoViewers(t *testing.T) {
	if testing.Short() {
		t.Skip("QA two-viewers joint: skips under -short (builds binaries + subprocesses)")
	}
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("QA two-viewers joint needs %s on PATH (fixture generation + probing; INV4: optional binary): %v", bin, err)
		}
	}

	root := t.TempDir()
	qaTwoViewWriteFixtures(t, root)
	up := qaTwoViewStartUpstream(t)
	j := qaTwoViewStartJoint(t, up, root)

	// --- enriched_baseline (fatal, not subtest): the shared substrate ---
	if res := scanLibrary(t, j.client, j.srv.baseURL, j.admin, j.lib); res.Discovered != 3 || res.Persisted != 3 {
		t.Fatalf("scan: discovered=%d persisted=%d, want 3/3 (1 serial record + 2 episodes); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	qaSerialWaitSettled(t, j.client, j.srv.baseURL, j.admin, j.lib)

	// Await BOTH namespaces (parser + shikimori, with the poster) — without
	// them the muted viewer's floor would be vacuous (nothing to floor past).
	var sr qaTwoViewSeries
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for {
		rows := qaTwoViewSeriesRows(t, j, j.admin)
		if len(rows) == 1 && rows[0].Status == "ready" {
			doc := parseAsyncDoc(t, rows[0].Document)
			if doc.Sources["serial-parser"] != nil && doc.Sources[qaTwoViewPlugin] != nil {
				shik, _ := doc.Sources[qaTwoViewPlugin]["title"].(map[string]any)
				poster, _ := doc.Sources[qaTwoViewPlugin]["poster"].(string)
				if asyncStr(shik, "russian") == qaTwoViewRussian && poster != "" {
					sr = rows[0]
					break
				}
			}
		}
		if time.Now().After(deadline) {
			t.Fatalf("series never enriched with parser+shikimori namespaces: %+v; upstream: %v", rows, up.snapshot())
		}
		time.Sleep(probeInterval)
	}
	if n := up.deriveCalls(); n != 1 {
		t.Fatalf("upstream saw %d derive calls after the drain, want exactly 1 (the search leg): %v", n, up.seen)
	}
	ep1 := qaTwoViewItemRow(t, qaTwoViewItemRows(t, j, j.admin), qaTwoViewEp1Rel)
	ep2 := qaTwoViewItemRow(t, qaTwoViewItemRows(t, j, j.admin), qaTwoViewEp2Rel)

	// The stored-namespace baseline: captured BEFORE any viewer serve, as the
	// env-admin. Every later byte-identity claim compares against THIS.
	baseline := qaTwoViewCapture(t, j, sr, ep1, ep2)
	if len(baseline.SeriesDoc) == 0 || len(baseline.Ep1Doc) == 0 {
		t.Fatalf("baseline documents empty (series %d bytes, ep1 %d bytes)", len(baseline.SeriesDoc), len(baseline.Ep1Doc))
	}

	// --- the REAL identity chain: users → groups → grants → mute doc → logins ---
	qaTwoViewCreateUser(t, j, qaTwoViewMutedUsername)
	qaTwoViewCreateUser(t, j, qaTwoViewCleanUsername)
	mutedGroup := qaTwoViewCreateGroup(t, j, qaTwoViewMutedGroup)
	cleanGroup := qaTwoViewCreateGroup(t, j, qaTwoViewCleanGroup)
	qaTwoViewAddMember(t, j, mutedGroup, qaTwoViewMutedUsername)
	qaTwoViewAddMember(t, j, cleanGroup, qaTwoViewCleanUsername)
	qaTwoViewAddCollection(t, j, mutedGroup, j.lib)
	qaTwoViewAddCollection(t, j, cleanGroup, j.lib)
	// THE MUTE — through the REAL doc endpoint: the same shape ResolveViewer's
	// mute-wins merge reads.
	qaTwoViewPutDoc(t, j, mutedGroup, map[string]any{"mutes": map[string]bool{qaTwoViewPlugin: true}})
	j.muted = qaTwoViewLogin(t, j, qaTwoViewMutedUsername)
	j.clean = qaTwoViewLogin(t, j, qaTwoViewCleanUsername)

	t.Run("muted_serve_floors", func(t *testing.T) {
		// The muted source's RU pick never surfaces and no artwork composes.
		qaTwoViewRequireFloored(t, j, j.muted)
		// The served chain carries the mute: shikimori rides with enabled=false
		// (the convention projection must SEE the mute, not lose the entry).
		chain := qaTwoViewChainOf(t, j, j.muted)
		found := false
		for _, b := range chain {
			if b.ID == qaTwoViewPlugin {
				found = true
				if b.Enabled {
					t.Errorf("muted viewer's source_chain carries %s enabled=true, want false", qaTwoViewPlugin)
				}
			}
		}
		if !found {
			t.Errorf("muted viewer's source_chain lacks %s entirely: %+v (the entry must ride enabled=false, never vanish)", qaTwoViewPlugin, chain)
		}
	})

	t.Run("clean_serve_composes", func(t *testing.T) {
		// The clean viewer composes the chain's natural first source: the RU
		// pick on both surfaces, the staged poster token as artwork (deterministic
		// — the content address is precomputed from the served bytes).
		srClean := qaTwoViewAwaitArtwork(t, j, j.clean, qaTwoViewArtwork)
		if srClean.Display != qaTwoViewRussian {
			t.Errorf("clean series display = %q, want the RU pick %q", srClean.Display, qaTwoViewRussian)
		}
		want := map[string]string{
			qaTwoViewEp1Rel: qaTwoViewRussian + " · S01E01",
			qaTwoViewEp2Rel: qaTwoViewRussian + " · S01E02",
		}
		for _, it := range qaTwoViewItemRows(t, j, j.clean) {
			if it.Display != want[it.RelativePath] {
				t.Errorf("clean item %q display = %q, want the composed %q", it.RelativePath, it.Display, want[it.RelativePath])
			}
			if it.Artwork == nil || *it.Artwork != qaTwoViewArtwork {
				t.Errorf("clean item %q artwork = %v, want the staged series poster %q (the lazy series fallback)", it.RelativePath, it.Artwork, qaTwoViewArtwork)
			}
		}
		// The clean chain carries the source enabled.
		chain := qaTwoViewChainOf(t, j, j.clean)
		found := false
		for _, b := range chain {
			if b.ID == qaTwoViewPlugin {
				found = true
				if !b.Enabled {
					t.Errorf("clean viewer's source_chain carries %s enabled=false, want true", qaTwoViewPlugin)
				}
			}
		}
		if !found {
			t.Errorf("clean viewer's source_chain lacks %s entirely: %+v", qaTwoViewPlugin, chain)
		}
	})

	t.Run("chain_diff_is_enabled_only", func(t *testing.T) {
		muted := qaTwoViewChainOf(t, j, j.muted)
		clean := qaTwoViewChainOf(t, j, j.clean)
		if len(muted) != len(clean) || len(muted) == 0 {
			t.Fatalf("chains differ in shape: muted %+v vs clean %+v", muted, clean)
		}
		// The structural diff EXCLUDING enabled is byte-EMPTY: same ids, same
		// order, same entry shape — only the flag moves.
		if !bytes.Equal(qaTwoViewChainSansEnabled(t, muted), qaTwoViewChainSansEnabled(t, clean)) {
			t.Fatalf("source_chain differs beyond the enabled flag:\nmuted (sans enabled): %s\nclean (sans enabled): %s",
				qaTwoViewChainSansEnabled(t, muted), qaTwoViewChainSansEnabled(t, clean))
		}
		for i := range muted {
			if muted[i].ID != clean[i].ID || muted[i].Enabled == clean[i].Enabled {
				continue
			}
			if muted[i].ID == qaTwoViewPlugin && !muted[i].Enabled && clean[i].Enabled {
				continue // THE one expected difference: the muted flag
			}
			t.Errorf("chain entry %d (%s): muted enabled=%v clean enabled=%v — an unexpected flag flip", i, muted[i].ID, muted[i].Enabled, clean[i].Enabled)
		}
	})

	t.Run("stored_namespaces_byte_identical", func(t *testing.T) {
		// AFTER both viewers' serves (repeated serves included — identity must
		// hold across reads, not one lucky pass): every stored namespace reads
		// back byte-identical against the pre-serve admin baseline. The floors
		// are per-response and never persist.
		for i := 0; i < 2; i++ {
			now := qaTwoViewCapture(t, j,
				qaTwoViewSeriesRow(t, qaTwoViewSeriesRows(t, j, j.admin)),
				qaTwoViewItemRow(t, qaTwoViewItemRows(t, j, j.admin), qaTwoViewEp1Rel),
				qaTwoViewItemRow(t, qaTwoViewItemRows(t, j, j.admin), qaTwoViewEp2Rel))
			qaTwoViewRequireIdentical(t, "admin re-serve after both viewers", baseline, now)
		}
	})

	t.Run("group_edits_wake_nothing", func(t *testing.T) {
		// MUTATION 1 — membership: the muted user joins the clean group. The
		// mute-wins merge must keep shikimori muted (one group's mute
		// silences), and the edit must wake nothing: zero derive calls, zero
		// stored bytes.
		qaTwoViewAddMember(t, j, cleanGroup, qaTwoViewMutedUsername)
		now := qaTwoViewCapture(t, j,
			qaTwoViewSeriesRow(t, qaTwoViewSeriesRows(t, j, j.admin)),
			qaTwoViewItemRow(t, qaTwoViewItemRows(t, j, j.admin), qaTwoViewEp1Rel),
			qaTwoViewItemRow(t, qaTwoViewItemRows(t, j, j.admin), qaTwoViewEp2Rel))
		qaTwoViewRequireIdentical(t, "membership edit", baseline, now)
		qaTwoViewRequireFloored(t, j, j.muted) // fresh serve — mute-wins holds

		// MUTATION 2 — the mute document itself: the muted group's doc drops
		// the mute. Stored namespaces STILL byte-identical (derivation is
		// group-blind — no stored row encodes group identity), still zero
		// derive calls — and a FRESH serve now composes the restored source:
		// the floors are live, resolved per request, never frozen.
		qaTwoViewPutDoc(t, j, mutedGroup, map[string]any{})
		now = qaTwoViewCapture(t, j,
			qaTwoViewSeriesRow(t, qaTwoViewSeriesRows(t, j, j.admin)),
			qaTwoViewItemRow(t, qaTwoViewItemRows(t, j, j.admin), qaTwoViewEp1Rel),
			qaTwoViewItemRow(t, qaTwoViewItemRows(t, j, j.admin), qaTwoViewEp2Rel))
		qaTwoViewRequireIdentical(t, "mute-document edit", baseline, now)
		srLive := qaTwoViewAwaitArtwork(t, j, j.muted, qaTwoViewArtwork)
		if srLive.Display != qaTwoViewRussian {
			t.Errorf("muted-user series display after the mute removal = %q, want the restored RU pick %q (the floors must be live, not frozen)", srLive.Display, qaTwoViewRussian)
		}
		for _, it := range qaTwoViewItemRows(t, j, j.muted) {
			want := qaTwoViewRussian + " · S01E01"
			if it.RelativePath == qaTwoViewEp2Rel {
				want = qaTwoViewRussian + " · S01E02"
			}
			if it.Display != want {
				t.Errorf("muted-user item %q display after the mute removal = %q, want %q", it.RelativePath, it.Display, want)
			}
		}
		// The restored chain matches the clean viewer's INCLUDING enabled.
		liveChain := qaTwoViewChainOf(t, j, j.muted)
		cleanChain := qaTwoViewChainOf(t, j, j.clean)
		if !bytes.Equal(qaTwoViewChainSansEnabled(t, liveChain), qaTwoViewChainSansEnabled(t, cleanChain)) {
			t.Errorf("chain shape moved after the doc edit: %+v vs %+v", liveChain, cleanChain)
		}

		// THE WAKE PROOF: across both viewers' serves, both mutations, and the
		// fresh serves — exactly ONE derive call ever hit the upstream (the
		// original search leg). Switching the user's groups wakes nothing.
		if n := up.deriveCalls(); n != 1 {
			t.Errorf("upstream saw %d derive calls after both group edits, want still 1 (derivation is group-blind): %v", n, up.snapshot())
		}
	})
}
